```javascript
class Cache {
  constructor(maxSize = 3) {
    this.maxSize = maxSize;
  }

  get(city) {
    const cache = JSON.parse(localStorage.getItem('cache')) || {};
    return cache[city] || null;
  }

  set(city, data) {
    const cache = JSON.parse(localStorage.getItem('cache')) || {};
    const cities = Object.keys(cache);

    if (cities.length >= this.maxSize && !cache[city]) {
      const oldestCity = cities.reduce((oldest, current) =>
        cache[current].timestamp < cache[oldest].timestamp ? current : oldest
      );
      delete cache[oldestCity];
    }

    cache[city] = {
      data,
      timestamp: Date.now()
    };

    localStorage.setItem('cache', JSON.stringify(cache));
  }
}
```

